export interface FormLayoutEntry {
  rows?: FormLayoutEntry[];
  [key: string]: any;
}

export function flattenGroupedFormLayout(
  formLayout: FormLayoutEntry[],
): FormLayoutEntry[] {
  const flattened: FormLayoutEntry[] = [];
  for (const element of formLayout) {
    if (element && Array.isArray(element.rows) && element.rows.length > 0) {
      flattened.push(...element.rows);
    } else {
      flattened.push(element);
    }
  }
  return flattened;
}
